package com.smartseating.dao;

import com.smartseating.model.Exam;
import com.smartseating.util.DBConnection;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class ExamDAO {
    private Exam map(ResultSet r)throws SQLException{return new Exam(r.getInt("id"),r.getString("exam_name"),r.getString("exam_type"),r.getDate("exam_date").toLocalDate(),r.getTime("start_time").toLocalTime(),r.getInt("duration_minutes"),r.getString("subject"),r.getString("academic_year"),r.getString("status"));}
    public List<Exam> findAll()throws SQLException{List<Exam>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM exams ORDER BY exam_date DESC,start_time");ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}return a;}
    public Exam findById(int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM exams WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
    public void save(Exam x,List<String> departments,List<String> semesters)throws SQLException{String sql="INSERT INTO exams(exam_name,exam_type,exam_date,start_time,duration_minutes,subject,academic_year,status) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){p.setString(1,x.getName());p.setString(2,x.getType());p.setDate(3,Date.valueOf(x.getDate()));p.setTime(4,Time.valueOf(x.getStartTime()));p.setInt(5,x.getDurationMinutes());p.setString(6,x.getSubject());p.setString(7,x.getAcademicYear());p.setString(8,x.getStatus());p.executeUpdate();try(ResultSet keys=p.getGeneratedKeys()){keys.next();x.setId(keys.getInt(1));}saveSelections(c,x.getId(),departments,semesters);c.commit();}catch(SQLException e){c.rollback();throw e;}}}
    private void saveSelections(Connection c,int examId,List<String> departments,List<String> semesters)throws SQLException{try(PreparedStatement d=c.prepareStatement("INSERT INTO exam_departments(exam_id,department_code) VALUES(?,?)");PreparedStatement s=c.prepareStatement("INSERT INTO exam_semesters(exam_id,semester_number) VALUES(?,?)")){for(String v:departments){d.setInt(1,examId);d.setString(2,v);d.addBatch();}for(String v:semesters){s.setInt(1,examId);s.setString(2,v);s.addBatch();}d.executeBatch();s.executeBatch();}}
    public void update(Exam x,List<String> departments,List<String> semesters)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("UPDATE exams SET exam_name=?,exam_type=?,exam_date=?,start_time=?,duration_minutes=?,subject=?,academic_year=?,status=? WHERE id=?")){p.setString(1,x.getName());p.setString(2,x.getType());p.setDate(3,Date.valueOf(x.getDate()));p.setTime(4,Time.valueOf(x.getStartTime()));p.setInt(5,x.getDurationMinutes());p.setString(6,x.getSubject());p.setString(7,x.getAcademicYear());p.setString(8,x.getStatus());p.setInt(9,x.getId());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("DELETE FROM exam_departments WHERE exam_id=?")){p.setInt(1,x.getId());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("DELETE FROM exam_semesters WHERE exam_id=?")){p.setInt(1,x.getId());p.executeUpdate();}saveSelections(c,x.getId(),departments,semesters);c.commit();} }
    public void delete(int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM exams WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}
    public List<String> selectedDepartments(int examId)throws SQLException{return selected("SELECT department_code FROM exam_departments WHERE exam_id=?",examId);}
    public List<String> selectedSemesters(int examId)throws SQLException{return selected("SELECT semester_number FROM exam_semesters WHERE exam_id=?",examId);}
    private List<String> selected(String sql,int id)throws SQLException{List<String>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(r.getString(1));}}return a;}
    public long countUpcoming()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM exams WHERE exam_date>=CURRENT_DATE AND status='SCHEDULED'");ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}
}
